nodes.notes:
Triggers research comparison for all leads.

POST /webhook/research-compare
{
  "limit": 100,
  "status": "NEW"
}

parameters.jsCode:
// Aggregate comparison results for research analysis
const items = $input.all();

let totalLeads = items.length;
let agreements = 0;
let totalDelta = 0;
let totalRuleLatency = 0;
let totalMLLatency = 0;
let totalRFLatency = 0;

let categoryDistribution = {
  rules: { COLD: 0, WARM: 0, HOT: 0 },
  ml: { COLD: 0, WARM: 0, HOT: 0 },
  rf: { COLD: 0, WARM: 0, HOT: 0 }
};

for (const item of items) {
  const data = item.json;

  if (data.agreement) agreements++;
  totalDelta += data.delta || 0;
  totalRuleLatency += data.ruleLatencyMs || 0;
  totalMLLatency += data.mlLatencyMs || 0;
  totalRFLatency += data.rfLatencyMs || 0;

  // Count category distribution
  if (data.ruleCategory) categoryDistribution.rules[data.ruleCategory]++;
  if (data.mlCategory) categoryDistribution.ml[data.mlCategory]++;
  if (data.rfCategory) categoryDistribution.rf[data.rfCategory]++;
}

return [{
  json: {
    summary: {
      totalLeads,
      agreementRate: (agreements / totalLeads * 100).toFixed(2) + '%',
      avgDelta: (totalDelta / totalLeads).toFixed(2),
      avgLatency: {
        rules: (totalRuleLatency / totalLeads).toFixed(2) + 'ms',
        ml: (totalMLLatency / totalLeads).toFixed(2) + 'ms',
        rf: (totalRFLatency / totalLeads).toFixed(2) + 'ms'
      },
      categoryDistribution
    },
    timestamp: new Date().toISOString()
  }
}];
